svg.script:
test(() => {
  const box = document.getElementById("image").getBBox();
  assert_equals(box.x, 25);
  assert_equals(box.y, 30);
  assert_equals(box.width, 40);
  assert_equals(box.height, 20);
}, "Image getBBox() uses CSS position and size over presentation attributes");

test(() => {
  const box = document.getElementById("foreign").getBBox();
  assert_equals(box.x, 70);
  assert_equals(box.y, 20);
  assert_equals(box.width, 100);
  assert_equals(box.height, 40);
}, "ForeignObject getBBox() resolves CSS percentage size against the SVG viewport");

test(() => {
  const image = document.getElementById("image");
  image.style.x = "55px";
  image.style.height = "30px";
  const box = image.getBBox();
  assert_equals(box.x, 55);
  assert_equals(box.height, 30);
}, "Changing image CSS geometry updates getBBox()");
